        });
      }
    }
  },
  data: function data() {
    return {
      tableHeight: undefined,
      total: 0,
      tableLoading: false,
      selectedImage: '',
      swerkList: [],
      addData: {
        imgBase64: '',
        name: '',
        roomDataId: '',
        companyId: '',
